MOD = 1000000007

def fibPair(n):
    # returns (F_n, F_(n+1)) modulo MOD
    if n == 0:
        return 0, 1
    a, b = fibPair(n // 2)
    c = a * ((2 * b - a) % MOD) % MOD  # F_(2k)
    d = (a * a + b * b) % MOD          # F_(2k+1)
    if n % 2 == 0:
        return c, d
    return d, (c + d) % MOD

def fibSquareSumMod(n):
    fn, fn1 = fibPair(n)
    return fn * fn1 % MOD
